create table if not exists public.lina_cms_content(id uuid primary key,user_scope text not null default 'public',type text not null,slug text not null,title text not null,status text not null default 'draft' check(status in ('draft','review','published','archived')),payload jsonb not null default '{}'::jsonb,content_version bigint not null default 1,updated_by text not null,updated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(type,slug));create table if not exists public.lina_cms_content_versions(id bigint generated by default as identity primary key,content_id uuid not null references public.lina_cms_content(id) on delete cascade,version bigint not null,payload jsonb not null,status text not null,saved_by text not null,saved_at timestamptz not null,unique(content_id,version));alter table public.lina_cms_content enable row level security;alter table public.lina_cms_content_versions enable row level security;